import numpy as np
import time


def _R(L):
    # L: knot values of f*f including zeros at both ends
    s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:])
    l1 = np.sum(np.diff(L))  # = sum of interior? no
    return s


def _score(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    l1 = np.sum(h) ** 2
    mx = np.max(L)
    if mx <= 0 or l1 <= 0:
        return 0.0
    return num / (l1 * mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best = np.ones(50, dtype=float)
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            best = s.copy()

    best_score = _score(best)

    # Try a smooth bump shape: the flat top gives a triangular autoconvolution;
    # a rounded bump tends to concentrate f*f more, raising R.
    # Use a raised-cosine / parabolic-like profile over a range of widths.
    N = 50
    for w in range(3, N + 1):
        x = np.linspace(-1.0, 1.0, w)
        # parabola-ish bump, non-negative
        h = np.clip(1.0 - x * x, 0.0, None)
        if np.sum(h) <= 0:
            continue
        sc = _score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()
        if time.process_time() > deadline:
            break

    # Try triangular ramps of various widths
    for w in range(2, N + 1):
        h = np.minimum(np.arange(w), np.arange(w)[::-1]) + 1.0
        sc = _score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()
        if time.process_time() > deadline:
            break

    # Try shapes with heavier tails: h ~ 1/sqrt(1+x^2) style
    for w in range(3, N + 1):
        x = np.linspace(-3.0, 3.0, w)
        h = 1.0 / (1.0 + x * x)
        sc = _score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()
        if time.process_time() > deadline:
            break

    return np.asarray(best, dtype=float)

import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    # ||f*f||_2^2
    l2 = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = np.sum(h)**2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    # Grid on [0,5] with N=2001 steps
    N = 2001
    dx = 5.0 / N
    x = (np.arange(N) + 0.5) * dx

    best_h = None
    best_r = -1.0

    ds = np.linspace(0.1, 1.5, 15)
    amps = [0.5, 0.75, 1.0, 1.25, 1.5, 2.0]

    for d in ds:
        for a in amps:
            if time.process_time() - t0 > budget_seconds * 0.85:
                break
            h = (1.0 * ((x >= 0.0) & (x <= 1.0))
                 + a * ((x >= d) & (x <= d + 1.0)))
            r = _R(h)
            if r > best_r:
                best_r = r
                best_h = h
        if time.process_time() - t0 > budget_seconds * 0.85:
            break

    if best_h is None:
        # fallback
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    print("best R = %.9f" % best_r)
    return best_h

import numpy as np
import time


def _R_from_conv(conv, s, linf_hint=None):
    """R given the (already computed) autoconvolution array conv."""
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0 or s <= 0:
        return -1.0
    return l2sq / (s * s * linf)


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    return _R_from_conv(np.convolve(h, h), s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.72

    # Set up starting shape
    if start is not None:
        h = np.asarray(start, dtype=float).ravel().copy()
        h = np.maximum(h, 0.0)
        if h.size == 0 or h.sum() <= 0:
            h = None
    else:
        h = None

    if h is None:
        N = 4001
        x = np.linspace(-1.0, 1.0, N)
        h = np.clip(np.cos(0.5 * np.pi * x), 0.0, None) ** 0.5
        h = np.minimum(h, 1.0)

    N = h.size
    nfft = 1
    while nfft < 2 * N - 1:
        nfft <<= 1

    def rfft_conv(hh):
        return np.fft.irfft(np.fft.rfft(hh, nfft) ** 2, nfft)[:2 * N - 1]

    def score_fft(hh):
        s = hh.sum()
        if s <= 0:
            return -1.0
        return _R_from_conv(rfft_conv(hh), s)

    best_h = h.copy()
    best_r = score_fft(best_h)

    # Fast local coordinate ascent in "shape space".
    # Key trick: we exploit that f*f, ||f||_1, and ||f*f||_inf are smooth in h,
    # and use a small set of multiplicative + additive perturbations with a
    # shrinking step size schedule. We also do a "flat-region" pass, where
    # the profile is nearly constant (the top of the rounded box) and small
    # perturbations matter most there.
    def coord_ascent(h, budget_end, step_schedule):
        h = h.copy()
        cur_r = score_fft(h)
        Nl = h.size
        # Precompute indices ordered by a heuristic: corners first (they bend
        # the box), then bulk. We alternate passes over corners and bulk.
        for step in step_schedule:
            if time.process_time() > budget_end:
                return h, cur_r
            mx = h.max() if h.max() > 0 else 1.0
            improved = False
            # Pass 1: multiplicative
            for i in range(Nl):
                if time.process_time() > budget_end:
                    return h, cur_r
                hi = h[i]
                cands = [hi * (1.0 + step), hi * (1.0 - step),
                         hi * (1.0 + 2 * step), hi * (1.0 - 2 * step)]
                lb = cur_r
                lv = hi
                for v in cands:
                    if v < 0 or v == hi:
                        continue
                    h[i] = v
                    r = score_fft(h)
                    if r > lb:
                        lb = r
                        lv = v
                h[i] = lv
                if lb > cur_r:
                    cur_r = lb
                    improved = True
            if not improved:
                # Pass 2: additive with magnitude step*mx
                for i in range(Nl):
                    if time.process_time() > budget_end:
                        return h, cur_r
                    hi = h[i]
                    d1 = step * mx
                    cands = [hi + d1, hi - d1, hi + 2 * d1, hi - 2 * d1]
                    lb = cur_r
                    lv = hi
                    for v in cands:
                        if v < 0 or v == hi:
                            continue
                        h[i] = v
                        r = score_fft(h)
                        if r > lb:
                            lb = r
                            lv = v
                    h[i] = lv
                    if lb > cur_r:
                        cur_r = lb
                        improved = True
            if not improved:
                break
        return h, cur_r

    # Coarse-to-fine: first a downsampled version to find the profile, then
    # full resolution. Downsampling is crucial because full-res coordinate
    # ascent over 4001 points in 30s with FFT conv is too slow to converge.
    def downsample(hh, k):
        if k <= 1:
            return hh.copy()
        n = hh.size
        m = (n // k) * k
        if m < k:
            return hh.copy()
        return hh[:m].reshape(-1, k).mean(axis=1)

    def upsample(hh, n):
        x_old = np.linspace(0.0, 1.0, hh.size)
        x_new = np.linspace(0.0, 1.0, n)
        return np.maximum(np.interp(x_new, x_old, hh), 0.0)

    # Multi-resolution ladder
    ladder = [(100, [0.15, 0.08]), (200, [0.1, 0.05]),
              (400, [0.06, 0.03]), (800, [0.03, 0.015])]
    cur = best_h
    for k, steps in ladder:
        if time.process_time() > deadline:
            break
        nfft_local = nfft
        # work on downsampled
        if k < N:
            hd = downsample(cur, N // k if N // k >= 1 else 1)
        else:
            hd = cur.copy()
        # temporarily replace score function to use hd's nfft
        # (compute directly)
        def score_hd(hh):
            s = hh.sum()
            if s <= 0:
                return -1.0
            nf = 1
            while nf < 2 * hh.size - 1:
                nf <<= 1
            conv = np.fft.irfft(np.fft.rfft(hh, nf) ** 2, nf)[:2 * hh.size - 1]
            return _R_from_conv(conv, s)

        hd = hd.copy()
        cur_r_d = score_hd(hd)
        Nd = hd.size
        for step in steps:
            if time.process_time() > deadline:
                break
            mx = hd.max() if hd.max() > 0 else 1.0
            improved = False
            for i in range(Nd):
                if time.process_time() > deadline:
                    break
                hi = hd[i]
                cands = [hi * (1.0 + step), hi * (1.0 - step),
                         hi + step * mx, hi - step * mx]
                lb = cur_r_d
                lv = hi
                for v in cands:
                    if v < 0 or v == hi:
                        continue
                    hd[i] = v
                    r = score_hd(hd)
                    if r > lb:
                        lb = r
                        lv = v
                hd[i] = lv
                if lb > cur_r_d:
                    cur_r_d = lb
                    improved = True
            if not improved:
                break
        # upsample back to full N and rescore
        full = upsample(hd, N)
        r_full = score_fft(full)
        if r_full > best_r:
            best_h = full
            best_r = r_full
        cur = full
        if time.process_time() > deadline:
            break

    # Final full-resolution polish with small steps
    if time.process_time() < deadline:
        polished, pr = coord_ascent(best_h, deadline, [0.01, 0.004])
        if pr > best_r:
            best_h, best_r = polished, pr

    # Basin hopping: small structured perturbations
    rng = np.random.RandomState(2024)
    for _ in range(4):
        if time.process_time() > deadline:
            break
        h = best_h.copy()
        # perturb a contiguous window near the top
        k = max(2, N // 50)
        c = rng.randint(N)
        lo = max(0, c - k)
        hi = min(N, c + k)
        h[lo:hi] *= rng.uniform(0.85, 1.15, size=hi - lo)
        h = np.maximum(h, 0.0)
        r = score_fft(h)
        if r > best_r:
            best_h, best_r = h, r
        # try a descent
        if time.process_time() < deadline:
            h2, r2 = coord_ascent(best_h, deadline, [0.008, 0.003])
            if r2 > best_r:
                best_h, best_r = h2, r2

    if best_r <= 0:
        best_h = np.ones(N)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _fft(h, nfft):
    return np.fft.rfft(h, nfft)


def _conv_L_from_H(H, N, nfft):
    conv = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    return L


def _A_and_dA(L):
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    dA = np.zeros_like(L)
    dA[:-1] += (2.0 * a + b) / 3.0
    dA[1:] += (a + 2.0 * b) / 3.0
    return A, dA


def _grad_from_dL(h, dL, H, nfft, N, s, scale_s_term):
    dR_dconv = dL[1:-1]
    D = np.fft.rfft(dR_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    return 2.0 * c + scale_s_term


def _R_grad_exact(h):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = _fft(h, nfft)
    L = _conv_L_from_H(H, N, nfft)
    A, dA = _A_and_dA(L)
    B = s * s
    j = int(np.argmax(L))
    M = L[j]
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)
    dL = dA / (B * M)
    dL[j] -= A / (B * M * M)
    grad = _grad_from_dL(h, dL, H, nfft, N, s, -A / (B * B * M) * 2.0 * s)
    return R, grad


def _R_grad_smooth(h, p):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = _fft(h, nfft)
    L = _conv_L_from_H(H, N, nfft)
    A, dA = _A_and_dA(L)
    B = s * s
    Lp = np.maximum(L, 0.0)
    Sp = np.sum(Lp ** p) + 1e-12
    M = Sp ** (1.0 / p)
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)
    dM_dL = (Lp ** (p - 1)) * (M ** (1 - p))
    dL = dA / (B * M) - A / (B * M * M) * dM_dL
    grad = _grad_from_dL(h, dL, H, nfft, N, s, -A / (B * B * M) * 2.0 * s)
    return R, grad


def _opt(h0, fg, maxiter, ftol=1e-15, gtol=1e-12):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    bounds = [(0.0, None)] * h0.size
    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': ftol, 'gtol': gtol})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _smooth_opt(h0, p, maxiter):
    def fg(x):
        r, g = _R_grad_smooth(x, p)
        return -r, -g
    return _opt(h0, fg, maxiter, ftol=1e-14, gtol=1e-10)


def _exact_opt(h0, maxiter):
    def fg(x):
        r, g = _R_grad_exact(x)
        return -r, -g
    return _opt(h0, fg, maxiter)


def _resample(h, N_target):
    if h.size == N_target:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, N_target)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    end = t0 + budget_seconds * 0.80

    N_target = 8001
    best_h = None
    best_r = -1.0

    if start is not None:
        s_arr = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if s_arr.size and s_arr.sum() > 0:
            best_r = _R(s_arr)
            best_h = s_arr.copy()

    # Candidate working arrays to explore from
    seeds = []
    if best_h is not None:
        seeds.append(_resample(best_h, N_target))
    # A triangular fresh seed
    x = np.linspace(-1.0, 1.0, 4001)
    tri = np.maximum(1.0 - np.abs(x), 0.0)
    seeds.append(_resample(tri, N_target))

    for seed in seeds:
        if seed.sum() <= 0:
            continue
        h = seed / seed.max()
        r = _R(h)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    if best_h is None:
        best_h = np.ones(N_target)
        best_r = _R(best_h)

    # Phase 1: smooth continuation from best, then exact polish
    h = best_h.copy()
    for p in (10, 30, 80, 200, 500, 1500):
        if time.process_time() > end:
            break
        h_try = _smooth_opt(h, p, 300)
        r_try = _R(h_try)
        if r_try > best_r:
            best_r = r_try
            best_h = h_try.copy()
        h = h_try

    if time.process_time() < end:
        h_try = _exact_opt(best_h, 800)
        r_try = _R(h_try)
        if r_try > best_r:
            best_r = r_try
            best_h = h_try.copy()

    # Phase 2: support trimming + exact reoptimization, with shrinking perturbations
    rng = np.random.default_rng(12345)
    base = best_h.copy()
    # Iteratively try various thresholds and noise levels
    attempts = [
        (0.0, 0.0), (0.001, 0.0), (0.003, 0.0), (0.008, 0.0),
        (0.0, 0.002), (0.002, 0.002), (0.005, 0.005),
    ]
    for frac_th, noise in attempts:
        if time.process_time() > end:
            break
        h_try = base.copy()
        if frac_th > 0:
            h_try[h_try < frac_th * h_try.max()] = 0.0
        if noise > 0:
            h_try = np.maximum(h_try * (1.0 + noise * rng.standard_normal(h_try.size)), 0.0)
        h_try = _exact_opt(h_try, 400)
        r_try = _R(h_try)
        if r_try > best_r:
            best_r = r_try
            best_h = h_try.copy()
            base = h_try.copy()

    # Phase 3: alternating exact-max polish (block coordinate style)
    for _ in range(40):
        if time.process_time() > end:
            break
        h_try = _exact_opt(best_h, 60)
        r_try = _R(h_try)
        if r_try > best_r + 1e-12:
            best_r = r_try
            best_h = h_try.copy()
        else:
            # tiny jitter to escape
            hj = best_h * (1.0 + 0.001 * rng.standard_normal(best_h.size))
            hj = np.maximum(hj, 0.0)
            h_try = _exact_opt(hj, 120)
            r_try = _R(h_try)
            if r_try > best_r:
                best_r = r_try
                best_h = h_try.copy()
            else:
                break

    if start is not None:
        s_arr = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if s_arr.size and _R(s_arr) > best_r:
            return s_arr

    return np.maximum(best_h, 0.0)

import numpy as np
import time
import random
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    return l2sq / (s * s * L.max())


def _conv_fft(h):
    N = h.size
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = np.fft.rfft(h, nfft)
    conv = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    return conv, H, nfft


def _Rs_and_grad_exact(h):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    conv, H, nfft = _conv_fft(h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = conv
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = s * s
    M = L.max()
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)

    dA_dL = np.zeros_like(L)
    dA_dL[:-1] += (2.0 * a + b) / 3.0
    dA_dL[1:] += (a + 2.0 * b) / 3.0

    act = L >= M * (1.0 - 1e-10)
    nact = act.sum()
    if nact == 0:
        act = np.zeros_like(L, dtype=bool); act[np.argmax(L)] = True; nact = 1
    dM_dL = act.astype(float) / nact

    dR_dL = dA_dL / (B * M) - A / (B * M * M) * dM_dL
    dR_dh_direct = -A / (B * B * M) * 2.0 * s * np.ones_like(h)

    dR_dconv = dR_dL[1:-1]
    D = np.fft.rfft(dR_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dR_dh_direct
    return R, grad


def _polish_exact(h0, maxiter):
    def fg(x):
        r, g = _Rs_and_grad_exact(x)
        return -r, -g
    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h0.size,
                       options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _polish_active(h0, idx, maxiter):
    if idx.size == 0:
        return h0
    base = h0.copy()
    x0 = base[idx].copy()

    def fg(x):
        base[idx] = x
        r, g = _Rs_and_grad_exact(base)
        return -r, -g[idx]

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * idx.size,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-12})
        base[idx] = np.maximum(res.x, 0.0)
        return base
    except Exception:
        base[idx] = x0
        return base


def _refine(h, N_new):
    N = h.size
    if N == N_new:
        return h.copy()
    x_old = (np.arange(N) + 0.5) / N
    x_new = (np.arange(N_new) + 0.5) / N_new
    hn = np.interp(x_new, x_old, h)
    if hn.sum() > 0:
        hn *= (h.sum() / N) / (hn.sum() / N_new)
    return np.maximum(hn, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds * 0.93

    if start is not None:
        h = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if h.sum() <= 0:
            h = None
    else:
        h = None

    if h is None:
        x = np.linspace(-1.0, 1.0, 4001)
        h = np.maximum(1.0 - np.abs(x), 0.0)

    if h.sum() <= 0:
        h = np.ones(4001)
    h = h / h.max()

    best_h = h.copy()
    best_r = _R(h)

    # Try a range of resolutions; the optimum is a smooth-ish shape so
    # upsampling + polish on several scales helps escape discretization.
    base_N = h.size
    candidates = [base_N]
    for N_try in (base_N * 2, base_N * 4, 8001, 16001, 24001, 32001):
        if 4000 <= N_try <= 50000 and N_try not in candidates:
            candidates.append(N_try)

    for N_try in candidates:
        if time.process_time() > hard_end:
            break
        if N_try == base_N:
            h_try = best_h.copy()
        else:
            h_try = _refine(best_h, N_try)
            r_try = _R(h_try)
            if r_try <= best_r:
                # still try polish from best at this resolution
                h_try = _refine(best_h, N_try)
        iters = 500 if N_try <= 16001 else 300
        h_pol = _polish_exact(h_try, iters)
        r_pol = _R(h_pol)
        if r_pol > best_r:
            best_r = r_pol
            best_h = h_pol

    # Active-set polish: only nonzero entries free, cap by budget.
    if time.process_time() < hard_end:
        nz = np.nonzero(best_h > 0)[0]
        h_pol = _polish_active(best_h, nz, 400)
        r_pol = _R(h_pol)
        if r_pol > best_r:
            best_r = r_pol
            best_h = h_pol

    # Final round of exact polishes on best.
    for _ in range(6):
        if time.process_time() > hard_end:
            break
        h_pol = _polish_exact(best_h, 400)
        r_pol = _R(h_pol)
        if r_pol > best_r + 1e-15:
            best_r = r_pol
            best_h = h_pol
        else:
            break

    if start is not None:
        hs = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if _R(hs) > best_r:
            return hs
    return best_h

import numpy as np
import time
import random
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _R_fft(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    N = h.size
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = np.fft.rfft(h, nfft)
    conv = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _conv_fft(h):
    N = h.size
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = np.fft.rfft(h, nfft)
    conv = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    return conv, H, nfft


def _Rs_and_grad_exact(h, active=None, eps=1e-9):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    conv, H, nfft = _conv_fft(h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = s * s
    M = L.max()
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)

    dA_dL = np.zeros_like(L)
    dA_dL[:-1] += (2.0 * a + b) / 3.0
    dA_dL[1:] += (a + 2.0 * b) / 3.0

    thr = M * (1.0 - eps)
    act = L >= thr
    nact = act.sum()
    if nact == 0:
        act = np.zeros_like(L, dtype=bool)
        act[np.argmax(L)] = True
        nact = 1
    dM_dL = act.astype(float) / nact

    dR_dL = dA_dL / (B * M) - A / (B * M * M) * dM_dL
    dR_dh_direct = -A / (B * B * M) * 2.0 * s * np.ones_like(h)

    dR_dconv = dR_dL[1:-1]
    D = np.fft.rfft(dR_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dR_dh_direct
    return R, grad


def _polish_exact(h0, maxiter, budget_end):
    N = h0.size
    bounds = [(0.0, None)] * N

    def fg(x):
        r, g = _Rs_and_grad_exact(x)
        return -r, -g

    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-11})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _perturb(h, rng):
    hh = h.copy()
    nz = np.nonzero(hh > 0)[0]
    if nz.size == 0:
        return hh
    action = rng.randrange(3)
    if action == 0:
        i = nz[rng.randrange(nz.size)]
        hh[i] = 0.0
    elif action == 1:
        i = nz[rng.randrange(nz.size)]
        cand = []
        if i > 0 and hh[i - 1] == 0:
            cand.append(i - 1)
        if i + 1 < hh.size and hh[i + 1] == 0:
            cand.append(i + 1)
        if cand:
            j = cand[rng.randrange(len(cand))]
            hh[j] = 0.5 * hh[i]
    else:
        i = nz[rng.randrange(nz.size)]
        lo = i
        while lo > 0 and hh[lo - 1] > 0:
            lo -= 1
        hi = i
        while hi + 1 < hh.size and hh[hi + 1] > 0:
            hi += 1
        direction = 1 if rng.random() < 0.5 else -1
        if direction == 1 and hi + 1 < hh.size:
            hh[lo + 1:hi + 2] = hh[lo:hi + 1].copy()
            hh[lo] = 0.0
        elif direction == -1 and lo - 1 >= 0:
            hh[lo - 1:hi] = hh[lo:hi + 1].copy()
            hh[hi] = 0.0
    return hh


def _downsample_avg(h, M):
    N = h.size
    if N % M != 0:
        x_old = np.linspace(0.0, 1.0, N)
        x_new = np.linspace(0.0, 1.0, M)
        return np.maximum(np.interp(x_new, x_old, h), 0.0)
    return h.reshape(M, N // M).mean(axis=1)


def _downsample_max(h, M):
    N = h.size
    if N % M != 0:
        x_old = np.linspace(0.0, 1.0, N)
        x_new = np.linspace(0.0, 1.0, M)
        return np.maximum(np.interp(x_new, x_old, h), 0.0)
    return h.reshape(M, N // M).max(axis=1)


def _upsample_lin(h, N):
    M = h.size
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.maximum(np.interp(x_new, x_old, h), 0.0)


def _upsample_rep(h, N):
    M = h.size
    if M == N:
        return h.copy()
    if N % M == 0:
        return np.repeat(h, N // M)
    return _upsample_lin(h, N)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget_end = t0 + budget_seconds * 0.85
    loop_end = t0 + budget_seconds * 0.95

    if start is not None:
        h = np.asarray(start, dtype=float).ravel()
        h = np.maximum(h, 0.0)
    else:
        x = np.linspace(-1.0, 1.0, 4001)
        h = 1.0 - np.abs(x)

    N_target = 16001
    if h.size != N_target:
        if N_target % h.size == 0:
            reps = N_target // h.size
            h = np.repeat(h, reps)
        else:
            x_old = np.linspace(0.0, 1.0, h.size)
            x_new = np.linspace(0.0, 1.0, N_target)
            h = np.interp(x_new, x_old, h)
        h = np.maximum(h, 0.0)

    if h.sum() <= 0:
        h = np.ones(N_target)
    h = h / h.max()

    best_h = h.copy()
    best_r = _R_fft(h)

    if start is not None:
        r_start = _R_fft(np.asarray(start, dtype=float).ravel())
        if r_start > best_r:
            best_r = r_start
            best_h = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)

    # Coarse-to-fine refinement: try several coarse sizes and both down/up schemes.
    coarse_sizes = [4001, 8001]
    schemes = [(_downsample_avg, _upsample_lin),
               (_downsample_max, _upsample_lin),
               (_downsample_avg, _upsample_rep)]

    for M in coarse_sizes:
        for down, up in schemes:
            if time.process_time() >= budget_end:
                break
            hc = down(best_h, M)
            if hc.sum() <= 0:
                continue
            hc = hc / hc.max()
            hc = _polish_exact(hc, 800, budget_end)
            r_c = _R_fft(hc)
            # Upsample and polish at full resolution.
            hu = up(hc, N_target)
            if hu.sum() <= 0:
                continue
            hu = hu / hu.max()
            hu = _polish_exact(hu, 800, budget_end)
            r_u = _R_fft(hu)
            if r_u > best_r + 1e-11:
                best_r = r_u
                best_h = hu
            # Also try the coarse solution directly if it beat current best at its scale
            # (not comparable across N, but upsample-polish handles it).

    # Full-resolution polish of current best.
    if time.process_time() < budget_end:
        h_try = _polish_exact(best_h, 2000, budget_end)
        r = _R_fft(h_try)
        if r > best_r:
            best_r = r
            best_h = h_try

    # Random support perturbation loop at full resolution.
    rng = random.Random(0)
    while time.process_time() < loop_end:
        h_try = _perturb(best_h, rng)
        h_try = _polish_exact(h_try, 300, loop_end)
        r = _R_fft(h_try)
        if r > best_r + 1e-10:
            best_r = r
            best_h = h_try

    return best_h

