    best_h = h.copy()
    best_r = _R(h)

    # Multi-resolution refinement of the start: polish at several N.
    # This is the main lever - the optimum appears to live near a specific
    # grid resolution, so try a spread of N values and keep the best.
    if time.process_time() < budget_end:
        Ns = [best_h.size]
        for f in (2, 3, 4):
            Ns.append(min(best_h.size * f, 50000))
        for N in (8001, 12001, 16001, 20001, 24001, 32001):
            Ns.append(N)
        seen = set()
        for N in Ns:
            if N in seen:
                continue
            seen.add(N)
            if time.process_time() >= budget_end:
                break
            h_up = _resample(best_h, N)
            if h_up.sum() <= 0:
                continue
            h_up = h_up / h_up.max()
            h_try = _polish_exact(h_up, 600, budget_end)
            r = _R(h_try)
            if r > best_r + 1e-13:
                best_r = r
                best_h = h_try

    # Final exact polish at best N.
    if time.process_time() < budget_end:
        h_try = _polish_exact(best_h, 3000, budget_end)
        r = _R(h_try)
        if r > best_r:
            best_r = r
            best_h = h_try

    # Deterministic support/boundary moves.
    while time.process_time() < hard_end:
        improved = False
        cands = _candidates(best_h)
        if not cands:
