            dM_dL[np.argmax(L)] = 1.0
    else:
        thr = M * (1.0 - eps)
        act = L >= thr
        nact = act.sum()
        if nact == 0:
            act = np.zeros_like(L, dtype=bool)
            act[np.argmax(L)] = True
            nact = 1
        dM_dL = act.astype(float) / nact

    dR_dL = dA_dL / (B * M) - A / (B * M * M) * dM_dL
    dR_dh_direct = -A / (B * B * M) * 2.0 * s

    dR_dconv = dR_dL[1:-1]
    D = np.fft.rfft(dR_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dR_dh_direct
    return R, grad


def _R_topk_and_grad(h, k):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    conv, H, nfft = _conv_fft(h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = s * s
    if A <= 0:
        return -1e9, np.zeros_like(h)
    nL = L.size
    kk = int(min(max(1, k), nL))
    if kk < nL:
        idx = np.argpartition(L, nL - kk)[nL - kk:]
    else:
        idx = np.arange(nL)
    M_k = L[idx].mean()
    if M_k <= 0:
        return -1e9, np.zeros_like(h)
    logS = np.log(A) - np.log(B) - np.log(M_k)

    dA_dL = np.zeros_like(L)
    dA_dL[:-1] += (2.0 * a + b) / 3.0
    dA_dL[1:] += (a + 2.0 * b) / 3.0

    dMk_dL = np.zeros_like(L)
    dMk_dL[idx] = 1.0 / kk

    dlogS_dL = dA_dL / A - dMk_dL / M_k
    dlogS_dh_direct = -2.0 / s

    dlogS_dconv = dlogS_dL[1:-1]
    D = np.fft.rfft(dlogS_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dlogS_dh_direct
    return logS, grad


def _logSp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    conv, H, nfft = _conv_fft(h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = s * s
    Lp = np.abs(L)
    Lp_pow = Lp ** p
    sum_pow = Lp_pow.sum()
    if sum_pow <= 0 or A <= 0:
        return -1e9, np.zeros_like(h)
    norm_p = sum_pow ** (1.0 / p)
    logS = np.log(A) - np.log(B) - np.log(norm_p)

    dA_dL = np.zeros_like(L)
    dA_dL[:-1] += (2.0 * a + b) / 3.0
    dA_dL[1:] += (a + 2.0 * b) / 3.0

    dnorm_dL = (Lp_pow / np.maximum(Lp, 1e-300)) * np.sign(L) / sum_pow
    dlogS_dL = dA_dL / A - dnorm_dL
    dlogS_dh_direct = -2.0 / s

    dlogS_dconv = dlogS_dL[1:-1]
    D = np.fft.rfft(dlogS_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dlogS_dh_direct
    return logS, grad


def _polish_exact(h0, maxiter, tau=None, eps=1e-9):
    N = h0.size
    bounds = [(0.0, None)] * N

    def fg(x):
        r, g = _Rs_and_grad_exact(x, eps=eps, tau=tau)
        return -r, -g

    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-11})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _polish_p(h0, p, maxiter):
    N = h0.size
    bounds = [(0.0, None)] * N

    def fg(x):
        r, g = _logSp_and_grad(x, p)
        return -r, -g

    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-11})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _polish_topk(h0, k, maxiter):
    N = h0.size
    bounds = [(0.0, None)] * N

    def fg(x):
        r, g = _R_topk_and_grad(x, k)
        return -r, -g

    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-11})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _topk_homotopy(h_cur, loop_end, ks=(2000, 1000, 500, 200, 100, 50, 20, 10, 5, 2, 1),
                   maxiter=800):
    Lsize = 2 * h_cur.size + 1
    for k in ks:
        if time.process_time() >= loop_end:
            break
        kk = min(k, Lsize)
        h_cur = _polish_topk(h_cur, kk, maxiter)
    return h_cur


def _find_runs(h):
    nz = h > 0
    runs = []
    i = 0
    N = h.size
    while i < N:
        if nz[i]:
            lo = i
            while i + 1 < N and nz[i + 1]:
                i += 1
            runs.append((lo, i))
        i += 1
    return runs


def _candidates(h):
    N = h.size
    runs = _find_runs(h)
    cands = []
    if not runs:
        return cands

    for (lo, hi) in runs:
        if hi > lo:
            c = h.copy(); c[lo] = 0.0; cands.append(c)
            c = h.copy(); c[hi] = 0.0; cands.append(c)
        if lo - 1 >= 0 and h[lo - 1] == 0:
            c = h.copy(); c[lo - 1] = 0.5 * h[lo]; cands.append(c)
        if hi + 1 < N and h[hi + 1] == 0:
            c = h.copy(); c[hi + 1] = 0.5 * h[hi]; cands.append(c)
        if hi - lo >= 2:
            seg = h[lo:hi + 1]
            k = lo + int(np.argmin(seg))
            if k > lo and k < hi:
                for gap in (1, 2):
                    c = h.copy()
                    c[k:k + gap] = 0.0
                    if np.any(c[lo:k] > 0) and np.any(c[k + gap:hi + 1] > 0):
                        cands.append(c)

    for i in range(len(runs) - 1):
        a_hi = runs[i][1]
        b_lo = runs[i + 1][0]
        gap = b_lo - a_hi - 1
        if 1 <= gap <= 2:
            c = h.copy()
            for j in range(a_hi + 1, b_lo):
                c[j] = min(h[a_hi], h[b_lo]) * 0.5
            cands.append(c)

    return cands


def _random_move(h, rng):
    N = h.size
    runs = _find_runs(h)
    move = rng.randint(0, 3)
    c = h.copy()
    if move == 0:
        if not runs:
            return None
        lo, hi = runs[rng.randrange(len(runs))]
        c[lo:hi + 1] = 0.0
        return c
    elif move == 1:
        cands = [(lo, hi) for (lo, hi) in runs if hi - lo >= 2]
        if not cands:
            return None
        lo, hi = cands[rng.randrange(len(cands))]
        k = rng.randint(lo + 1, hi - 1)
        gap = rng.randint(1, 3)
        c[k:k + gap] = 0.0
        if not (np.any(c[lo:k] > 0) and np.any(c[k + gap:hi + 1] > 0)):
            return None
        return c
    elif move == 2:
        hmax = h.max()
        if hmax <= 0:
            return None
        gaps = []
        i = 0
        while i < N:
            if h[i] == 0:
                lo = i
                while i + 1 < N and h[i + 1] == 0:
                    i += 1
                gaps.append((lo, i))
            i += 1
        if not gaps:
            return None
        lo, hi = gaps[rng.randrange(len(gaps))]
        width = rng.randint(1, min(hi - lo + 1, 8))
        st = rng.randint(lo, hi - width + 1)
        c[st:st + width] = rng.random() * hmax
        return c
    else:
        if not runs:
            return None
        lo, hi = runs[rng.randrange(len(runs))]
        if rng.random() < 0.5:
            if lo - 1 >= 0 and h[lo - 1] == 0:
                c[lo - 1] = h[lo]; c[lo] = 0.0; return c
            elif hi + 1 < N and h[hi + 1] == 0:
                c[hi + 1] = h[hi]; c[hi] = 0.0; return c
        else:
            if hi + 1 < N and h[hi + 1] == 0:
                c[hi + 1] = h[hi]; c[hi] = 0.0; return c
            elif lo - 1 >= 0 and h[lo - 1] == 0:
                c[lo - 1] = h[lo]; c[lo] = 0.0; return c
        return None


def _resample(h, N_new):
    N = h.size
    if N_new == N:
        return h.copy()
    idx = np.round(np.arange(N_new) * (N - 1) / (N_new - 1)).astype(int)
    idx = np.clip(idx, 0, N - 1)
    return h[idx].copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    loop_end = t0 + budget_seconds * 0.88

    if start is not None:
        h = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
    else:
        x = np.linspace(-1.0, 1.0, 4001)
        h = 1.0 - np.abs(x)

    if h.sum() <= 0:
        h = np.ones(max(1, h.size))
    m = h.max()
    if m > 0:
        h = h / m

    best_h = h.copy()
    best_r = _R(h)

    def try_h(h_try, thresh=1e-13):
        nonlocal best_h, best_r
        r = _R(h_try)
        if r > best_r + thresh:
            best_r = r
            best_h = h_try
            return True
        return False

    # Top-k homotopy on the starting shape.
    if time.process_time() < loop_end:
        h_cur = _topk_homotopy(best_h.copy(), loop_end)
        if _R(h_cur) > best_r - 1e-6:
            try_h(h_cur)
        if time.process_time() < loop_end:
            h_ex = _polish_exact(h_cur, 2000)
            try_h(h_ex)

    # NEW: resample to nearby N values and re-optimize.
    N0 = best_h.size
    for N_new in (12000, 14000, 18000, 20000, 24000):
        if time.process_time() >= loop_end:
            break
        if N_new > 50000:
            continue
        h_r = _resample(best_h, N_new)
        if h_r.sum() <= 0:
            continue
        if time.process_time() < loop_end:
            h_r = _topk_homotopy(h_r, loop_end)
        if time.process_time() < loop_end:
            h_r = _polish_exact(h_r, 3000)
        try_h(h_r)

    # Smooth p-norm homotopy.
    if time.process_time() < loop_end:
        h_cur = best_h.copy()
        for p in (64.0, 32.0, 16.0, 8.0, 4.0):
            if time.process_time() >= loop_end:
                break
            h_p = _polish_p(h_cur, p, 800)
            r_p = _R(h_p)
            if r_p > best_r - 1e-6:
                h_cur = h_p
                try_h(h_p)
        if time.process_time() < loop_end:
            h_ex = _polish_exact(h_cur, 2000)
            try_h(h_ex)

    # Softmax-temperature annealing on the Linf.
    for tau_rel in (1e-3, 1e-4, 1e-5):
        if time.process_time() >= loop_end:
            break
        M = best_h.max()
        if M <= 0:
            break
        h_s = _polish_exact(best_h, 1500, tau=tau_rel * M)
        if time.process_time() < loop_end:
            h_e = _polish_exact(h_s, 1500)
            try_h(h_e)

    # Repeated exact polishing with pruning.
    for _ in range(4):
        if time.process_time() >= loop_end:
            break
        h_try = _polish_exact(best_h, 3000)
        try_h(h_try)
        if time.process_time() >= loop_end:
            break
        hmax = best_h.max()
        h_prune = best_h.copy()
        h_prune[h_prune < 1e-9 * hmax] = 0.0
        try_h(_polish_exact(h_prune, 3000))

    # Support perturbation sweep with random moves.
    rng = random.Random(2024)
    stall = 0
    while time.process_time() < loop_end and stall < 250:
        improved = False
        for cand in _candidates(best_h):
            if time.process_time() >= loop_end:
                break
            if try_h(_polish_exact(cand, 600)):
                improved = True
                break
        if improved:
            stall = 0
            continue
        cand = _random_move(best_h, rng)
        if cand is not None and try_h(_polish_exact(cand, 600)):
            stall = 0
        else:
            stall += 1

    return best_h

import numpy as np
import time
import random
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _conv_fft(h):
    N = h.size
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = np.fft.rfft(h, nfft)
    conv = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    return conv, H, nfft


def _Rs_and_grad_exact(h, eps=1e-9, tau=None):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    conv, H, nfft = _conv_fft(h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = s * s
    M = L.max()
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)

    dA_dL = np.zeros_like(L)
    dA_dL[:-1] += (2.0 * a + b) / 3.0
    dA_dL[1:] += (a + 2.0 * b) / 3.0

    if tau is not None and tau > 0:
        w = np.exp((L - M) / tau)
        sw = w.sum()
        dM_dL = w / sw if sw > 0 else np.zeros_like(L)
        if sw <= 0:
            dM_dL[np.argmax(L)] = 1.0
    else:
        thr = M * (1.0 - eps)
        act = L >= thr
        nact = act.sum()
        if nact == 0:
            act = np.zeros_like(L, dtype=bool)
            act[np.argmax(L)] = True
            nact = 1
        dM_dL = act.astype(float) / nact

    dR_dL = dA_dL / (B * M) - A / (B * M * M) * dM_dL
    dR_dh_direct = -A / (B * B * M) * 2.0 * s

    dR_dconv = dR_dL[1:-1]
    D = np.fft.rfft(dR_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dR_dh_direct
    return R, grad


def _R_topk_and_grad(h, k):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    conv, H, nfft = _conv_fft(h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = s * s
    if A <= 0:
        return -1e9, np.zeros_like(h)
    nL = L.size
    kk = int(min(max(1, k), nL))
    if kk < nL:
        idx = np.argpartition(L, nL - kk)[nL - kk:]
    else:
        idx = np.arange(nL)
    M_k = L[idx].mean()
    if M_k <= 0:
        return -1e9, np.zeros_like(h)
    logS = np.log(A) - np.log(B) - np.log(M_k)

    dA_dL = np.zeros_like(L)
    dA_dL[:-1] += (2.0 * a + b) / 3.0
    dA_dL[1:] += (a + 2.0 * b) / 3.0

    dMk_dL = np.zeros_like(L)
    dMk_dL[idx] = 1.0 / kk

    dlogS_dL = dA_dL / A - dMk_dL / M_k
    dlogS_dh_direct = -2.0 / s

    dlogS_dconv = dlogS_dL[1:-1]
    D = np.fft.rfft(dlogS_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    grad = 2.0 * c + dlogS_dh_direct
    return logS, grad


def _logSp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
