        if hi - lo >= 2:
            seg = h[lo:hi + 1]
            k = lo + int(np.argmin(seg))
            if k > lo and k < hi:
                for gap in (1, 2):
                    c = h.copy()
                    c[k:k + gap] = 0.0
                    if np.any(c[lo:k] > 0) and np.any(c[k + gap:hi + 1] > 0):
