        if 1 <= gap <= 2:
            c = h.copy()
            for j in range(a_hi + 1, b_lo):
                c[j] = min(h[a_hi], h[b_lo]) * 0.5
            cands.append(c)

    return cands


def _random_move(h, rng):
    N = h.size
    runs = _find_runs(h)
    move = rng.randint(0, 3)
    c = h.copy()
    if move == 0:
        if not runs:
            return None
        lo, hi = runs[rng.randrange(len(runs))]
        c[lo:hi + 1] = 0.0
        return c
    elif move == 1:
        cands = [(lo, hi) for (lo, hi) in runs if hi - lo >= 2]
        if not cands:
            return None
        lo, hi = cands[rng.randrange(len(cands))]
        k = rng.randint(lo + 1, hi - 1)
        gap = rng.randint(1, 3)
        c[k:k + gap] = 0.0
        if not (np.any(c[lo:k] > 0) and np.any(c[k + gap:hi + 1] > 0)):
            return None
        return c
    elif move == 2:
        hmax = h.max()
        if hmax <= 0:
            return None
        gaps = []
        i = 0
        while i < N:
            if h[i] == 0:
                lo = i
                while i + 1 < N and h[i + 1] == 0:
                    i += 1
                gaps.append((lo, i))
            i += 1
        if not gaps:
            return None
        lo, hi = gaps[rng.randrange(len(gaps))]
        width = rng.randint(1, min(hi - lo + 1, 8))
        st = rng.randint(lo, hi - width + 1)
        c[st:st + width] = rng.random() * hmax
        return c
    else:
        if not runs:
            return None
        lo, hi = runs[rng.randrange(len(runs))]
        if rng.random() < 0.5:
            if lo - 1 >= 0 and h[lo - 1] == 0:
                c[lo - 1] = h[lo]; c[lo] = 0.0; return c
            elif hi + 1 < N and h[hi + 1] == 0:
                c[hi + 1] = h[hi]; c[hi] = 0.0; return c
        else:
            if hi + 1 < N and h[hi + 1] == 0:
                c[hi + 1] = h[hi]; c[hi] = 0.0; return c
            elif lo - 1 >= 0 and h[lo - 1] == 0:
                c[lo - 1] = h[lo]; c[lo] = 0.0; return c
        return None


def _topk_plateau(h, k, maxiter, deadline):
    """Polish with top-k plateau objective, then exact polish, return best."""
    if time.process_time() >= deadline:
        return None
    h_k = _polish_topk(h, k, maxiter)
    return h_k


def _maximize_plateau(h, deadline, maxiter=2500):
    """Directly maximize R with a sharper (smaller-eps) peak, to sharpen the max."""
    if time.process_time() >= deadline:
        return _polish_exact(h, maxiter, eps=1e-13)
    return _polish_exact(h, maxiter, eps=1e-13)


def construct(budget_seconds, start):
    t0 = time.process_time()
    loop_end = t0 + budget_seconds * 0.90

    if start is not None:
        h = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
    else:
        x = np.linspace(-1.0, 1.0, 4001)
        h = 1.0 - np.abs(x)

    if h.sum() <= 0:
        h = np.ones(max(1, h.size))
    m = h.max()
    if m > 0:
        h = h / m

    best_h = h.copy()
    best_r = _R(h)

    def try_h(h_try, thresh=1e-13):
        nonlocal best_h, best_r
        if h_try is None:
            return False
        r = _R(h_try)
        if r > best_r + thresh:
            best_r = r
            best_h = h_try
            return True
        return False

    # Focused top-k homotopy: k decreasing to 1, each followed by exact polish.
    if time.process_time() < loop_end:
        h_cur = best_h.copy()
        Lsize = 2 * h_cur.size + 1
        for k in (200, 100, 50, 20, 10, 5, 3, 2, 1):
            if time.process_time() >= loop_end:
                break
            kk = min(k, Lsize)
            h_k = _polish_topk(h_cur, kk, 400)
            r_k = _R(h_k)
            if r_k > best_r - 1e-7:
                h_cur = h_k
                try_h(h_k)
            if time.process_time() >= loop_end:
                break
            h_ex = _polish_exact(h_cur, 600, eps=1e-13)
            if try_h(h_ex):
                h_cur = h_ex
            else:
                h_cur = h_ex  # continue from polished state anyway

    # p-norm homotopy.
    if time.process_time() < loop_end:
        h_cur = best_h.copy()
        for p in (16.0, 8.0, 4.0, 2.0):
            if time.process_time() >= loop_end:
                break
            h_p = _polish_p(h_cur, p, 500)
            r_p = _R(h_p)
            if r_p > best_r - 1e-7:
                h_cur = h_p
                try_h(h_p)
            if time.process_time() >= loop_end:
                break
            h_ex = _polish_exact(h_cur, 600, eps=1e-13)
            if try_h(h_ex):
                h_cur = h_ex

    # Repeated exact polishing with sharp peak.
    for _ in range(6):
        if time.process_time() >= loop_end:
            break
        h_try = _polish_exact(best_h, 2000, eps=1e-13)
        try_h(h_try)
        hmax = best_h.max()
        if hmax > 0:
            h_prune = best_h.copy()
            h_prune[h_prune < 1e-10 * hmax] = 0.0
            if np.any(h_prune > 0):
                try_h(_polish_exact(h_prune, 2000, eps=1e-13))

    # Support perturbation sweep.
    rng = random.Random(12345)
    stall = 0
    while time.process_time() < loop_end and stall < 300:
        improved = False
        for cand in _candidates(best_h):
            if time.process_time() >= loop_end:
                break
            h_k = _polish_topk(cand, 1, 200)
            h_e = _polish_exact(h_k, 500, eps=1e-13)
            if try_h(h_e):
                improved = True
                break
        if improved:
            stall = 0
            continue
        cand = _random_move(best_h, rng)
        if cand is not None:
            h_k = _polish_topk(cand, 1, 200)
            h_e = _polish_exact(h_k, 500, eps=1e-13)
            if try_h(h_e):
                stall = 0
                continue
        stall += 1

    # Final sharp polish.
    if time.process_time() < loop_end:
        try_h(_polish_exact(best_h, 3000, eps=1e-13))

    return best_h
